{"command": "cat > ~/dose2.py <<'EOF'
import workcell,sys,re
tare=float(sys.argv[1]); target=tare+250.0
def rd():
    r=workcell.call("scale","read"); return float(re.search(r"([\d.]+) g",r.text).group(1))
for i in range(4): workcell.call("robot","dose","bulk")
w=rd(); print("bulk4",w-tare)
for i in range(60):
    rem=target-w
    if abs(rem)<=0.1: break
    if rem<-0.15: c="remove"
    elif rem>11: c="coarse"
    elif rem>0.8: c="fine"
    elif rem>0.05: c="micro"
    else: break
    if c=="remove": workcell.call("robot","remove")
    else: workcell.call("robot","dose",c)
    w=rd(); print(c, w, round(w-tare,2))
EOF
robot pick J2; robot place platform; python3 ~/dose2.py 123.70; checkweigher check; station status"}
